Open in PlaygroundDCB notationConsistency boundary<pre><code>model "Opt-in token"

// Types
tag type EmailAddress = string
tag type Otp = string

// Events
event SignUpInitiated { tag emailAddress: EmailAddress, tag otp: Otp, name: string }
event SignUpConfirmed { tag emailAddress: EmailAddress, tag otp: Otp, name: string }

// Projections
projection SignUpPending (tag emailAddress: EmailAddress, tag otp: Otp): boolean = false {
  on SignUpInitiated =&gt; set true
}

projection SignUpName (tag emailAddress: EmailAddress, tag otp: Otp): string = null {
  on SignUpInitiated =&gt; set event.data.name
}

projection OtpUsed (tag emailAddress: EmailAddress, tag otp: Otp): boolean = false {
  on SignUpConfirmed =&gt; set true
}

// Commands
command ConfirmSignUp(emailAddress: EmailAddress, otp: Otp) {
  alias pending = SignUpPending(emailAddress, otp)
  alias used = OtpUsed(emailAddress, otp)
  alias name = SignUpName(emailAddress, otp)

  require pending is true
    else reject "No sign-up is pending for this code"
  require used is false
    else reject "Code was already used"

  emit SignUpConfirmed { emailAddress, otp, name }

  scenarios {
    scenario "Confirm SignUp for non-existing OTP" {
      when ConfirmSignUp { emailAddress: "john.doe@example.com", otp: "000000" }
      then rejected "No sign-up is pending for this code"
    }

    scenario "Confirm SignUp for OTP assigned to different email address" {
      given SignUpInitiated { emailAddress: "john.doe@example.com", otp: "111111", name: "John Doe" }
      when ConfirmSignUp { emailAddress: "jane.doe@example.com", otp: "111111" }
      then rejected "No sign-up is pending for this code"
    }

    scenario "Confirm SignUp for already used OTP" {
      given SignUpInitiated { emailAddress: "john.doe@example.com", otp: "222222", name: "John Doe" }
      and SignUpConfirmed { emailAddress: "john.doe@example.com", otp: "222222", name: "John Doe" }
      when ConfirmSignUp { emailAddress: "john.doe@example.com", otp: "222222" }
      then rejected "Code was already used"
    }

    scenario "Confirm SignUp for valid OTP" {
      given SignUpInitiated { emailAddress: "john.doe@example.com", otp: "444444", name: "John Doe" }
      when ConfirmSignUp { emailAddress: "john.doe@example.com", otp: "444444" }
      then SignUpConfirmed { emailAddress: "john.doe@example.com", otp: "444444", name: "John Doe" }
    }
  }
}
</code></pre><p><code>ConfirmSignUp</code> reads 2 types, 2 tags</p>Query ItemEvent TypesTags<code>pending</code><code>SignUpInitiated</code><code>EmailAddress:{emailAddress}</code>, <code>Otp:{otp}</code><code>used</code><code>SignUpConfirmed</code><code>EmailAddress:{emailAddress}</code>, <code>Otp:{otp}</code><code>name</code><code>SignUpInitiated</code><code>EmailAddress:{emailAddress}</code>, <code>Otp:{otp}</code><p><code>AppendCondition</code>: <code>failIfEventsMatch</code> the Query above, <code>after</code> the position of the last Event read</p><p>Tags of the appended events: <code>EmailAddress:{emailAddress}</code>, <code>Otp:{otp}</code></p>

Open in PlaygroundDCB notationConsistency boundary<pre><code>model "Product reviews"

// Types
tag type ProductId = string
tag type CustomerId = string
type Rating = integer { minimum: 1, maximum: 5 }

// Events
event ProductReviewed {
  tag productId: ProductId
  tag customerId: CustomerId
  rating: Rating
}

// Projections
projection ProductReviewedByCustomer (tag productId: ProductId, tag customerId: CustomerId): boolean = false {
  on ProductReviewed =&gt; set true
}

// Commands
command ReviewProduct(productId: ProductId, customerId: CustomerId, rating: Rating) {
  require ProductReviewedByCustomer(productId, customerId) is false
    else reject "Customer already reviewed this product"

  emit ProductReviewed { productId, customerId, rating }

  scenarios {
    scenario "Review a product twice" {
      given ProductReviewed { productId: "p1", customerId: "c1", rating: 4 }
      when ReviewProduct { productId: "p1", customerId: "c1", rating: 5 }
      then rejected "Customer already reviewed this product"
    }

    scenario "Review a product another customer has reviewed" {
      given ProductReviewed { productId: "p1", customerId: "c2", rating: 4 }
      when ReviewProduct { productId: "p1", customerId: "c1", rating: 5 }
      then ProductReviewed { productId: "p1", customerId: "c1", rating: 5 }
    }

    scenario "Review another product" {
      given ProductReviewed { productId: "p2", customerId: "c1", rating: 4 }
      when ReviewProduct { productId: "p1", customerId: "c1", rating: 5 }
      then ProductReviewed { productId: "p1", customerId: "c1", rating: 5 }
    }
  }
}
</code></pre><p><code>ReviewProduct</code> reads 1 type, 2 tags</p>Query ItemEvent TypesTags<code>ProductReviewedByCustomer(customerId, productId)</code><code>ProductReviewed</code><code>ProductId:{productId}</code>, <code>CustomerId:{customerId}</code><p><code>AppendCondition</code>: <code>failIfEventsMatch</code> the Query above, <code>after</code> the position of the last Event read</p><p>Tags of the appended events: <code>ProductId:{productId}</code>, <code>CustomerId:{customerId}</code></p> <p>The "Consistency boundary" tab shows a single Query Item with the Tags <code>ProductId:p1</code> and <code>CustomerId:c1</code>. The Tags of a Query Item are combined with AND, so other customers reviewing the same product, or the same customer reviewing other products, do not affect the decision and can be appended in parallel.</p>

Annotation On Effect <code>@icon("📚")</code> events, commands (and entities) the symbol the playground shows it with <code>@feature("Enrolment")</code> commands the feature group the playground lists it under <code>@tagSchema("{type}={value}")</code> tag types how a Tag of the type is written, see <code>tag type</code> <pre><code>@feature("Course management")
@icon("✨")
command DefineCourse(capacity: Capacity) {
  emit CourseDefined { courseId: CourseNumbering(), capacity }
}</code></pre> <p>Annotations change how the DCB Playground presents a definition, not what it means. An annotation stands on the line before the definition.</p>
